import strawberry
from strawberry.file_uploads import Upload
from strawberry.types import Info

@strawberry.type
class FirmwareUpdateResult:
    device_uuid: str
    checksum: str
    status: str

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def flash_device_firmware(
        self,
        info: Info,
        device_uuid: str,
        firmware: Upload
    ) -> FirmwareUpdateResult:
        user = info.context.get("user")
        if not user:
            raise Exception("Authentication required")

        iot_manager = info.context["iot_device_manager"]
        device = await iot_manager.get_device_record(device_uuid)
        if not device or device.organization_id != user.organization_id:
            raise Exception("Device not found or not owned by your organization")

        firmware_bytes = await firmware.read()
        result = await iot_manager.dispatch_ota_update(
            device_uuid=device_uuid,
            firmware_blob=firmware_bytes
        )

        return FirmwareUpdateResult(
            device_uuid=device_uuid,
            checksum=result.sha256,
            status="QUEUED"
        )
